/*
 Problem: 3550. Smallest Index With Digit Sum Equal to Index
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 31 MB (48.54%)
 Tags: Array, Math
*/
class Solution {
public:
    int smallestIndex(vector<int>& nums) {
        for (int i = 0; i < nums.size(); ++i) {
            int x = nums[i], sum = 0;

            while (x) {
                sum += x % 10;
                x /= 10;
            }

            if (sum == i) return i;
        }

        return -1;
    }
};
